//=============================================================================
// Module: aes_uart_12m_top.sv
// Directory: uart_integration/common/
// Description: Board top for 12 Mbaud through the kit's USB-C port. The AES-GCM
//              engine stays on the 50 MHz oscillator; PF_CCC_120M (generated by
//              pf_ccc_120m.tcl) gives the UART 120 MHz, an exact 10 clocks per
//              bit. The same clock also divides 8, 6, 4, 3, 2 and 1 Mbaud.
//
// Target: Microchip PolarFire SoC Discovery Kit (MPFS095T-1FCSG325E)
//=============================================================================

`timescale 1ns / 1ps

module aes_uart_12m_top #(
    parameter int KEY_BITS  = 256,
    parameter int BAUD_RATE = 12_000_000
)(
    input  logic clk,
    input  logic rst_n,

    // FT4232HL channel D
    input  logic uart_rx,
    output logic uart_tx,

    // Status diagnostics
    output logic       led_busy,
    output logic       led_done,
    output logic [4:0] led_unused
);

    logic clk_global;
    logic clk_uart;
    logic pll_lock;

    CLKINT u_clk_buffer (
        .A(clk),
        .Y(clk_global)
    );

    PF_CCC_120M u_ccc (
        .REF_CLK_0        (clk_global),
        .PLL_POWERDOWN_N_0(1'b1),
        .OUT0_FABCLK_0    (clk_uart),
        .PLL_LOCK_0       (pll_lock)
    );

    aes_uart_cdc_wrapper #(
        .KEY_BITS   (KEY_BITS),
        .CLK_FREQ_HZ(50_000_000),
        .UART_CLK_HZ(120_000_000),
        .BAUD_RATE  (BAUD_RATE)
    ) u_uart (
        .clk       (clk_global),
        .clk_uart  (clk_uart),
        .rst_n     (rst_n & pll_lock),
        .uart_rx   (uart_rx),
        .uart_tx   (uart_tx),
        .led_busy  (led_busy),
        .led_done  (led_done),
        .led_unused(led_unused)
    );

endmodule
